#!/usr/bin/env bash
# Generates the Android launcher icons from the Paxve logo (needs rsvg-convert; present in Dockerfile.build).
set -euo pipefail
cd "$(dirname "$0")/.."
RES=android/app/src/main/res
TMP=$(mktemp -d)

# square icon (same as web favicon)
cat > "$TMP/icon.svg" <<'EOF'
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="14" fill="#0B1F3A"/><g transform="translate(0 0) scale(1)"><g transform="translate(-51.3 6.1) scale(0.03556)"><g transform="translate(0 1232) scale(0.25 -0.25)"><path d="M10626 3768 c-578 -31 -1016 -329 -1468 -1002 -31 -46 -104 -154 -162 -240 -58 -86 -141 -210 -184 -276 -490 -751 -888 -1177 -1438 -1537 -181 -118 -223 -161 -224 -225 -1 -164 405 -257 846 -196 419 59 786 307 1166 788 143 182 215 284 425 602 523 793 783 1108 1211 1469 31 26 95 79 142 119 142 119 242 208 264 235 106 127 26 207 -249 249 -103 16 -209 20 -329 14z M7574 3758 c-312 -32 -451 -85 -451 -171 0 -44 19 -62 237 -229 425 -324 766 -669 1090 -1103 107 -144 111 -144 229 40 34 55 91 142 125 194 34 52 83 127 108 166 25 39 74 110 108 157 127 177 131 156 -78 384 -394 431 -844 616 -1368 562z M9990 2003 c-25 -11 -83 -93 -295 -413 -58 -88 -144 -214 -192 -280 -124 -174 -124 -178 -58 -260 309 -381 542 -575 825 -687 426 -168 1095 -128 1304 79 86 85 61 136 -106 220 -108 54 -259 143 -337 199 -230 164 -369 285 -548 477 -173 185 -256 286 -455 549 -86 115 -105 131 -138 116z" fill="#fff"/><path d="M10601 3768 c-578 -48 -998 -340 -1443 -1002 -31 -46 -109 -162 -173 -257 -64 -95 -146 -218 -182 -274 -36 -55 -85 -129 -109 -163 -24 -34 -67 -97 -96 -139 -360 -521 -741 -899 -1244 -1233 -166 -110 -204 -150 -204 -212 1 -152 368 -249 772 -205 456 50 842 292 1205 753 28 36 73 93 98 125 70 88 226 311 302 429 282 440 577 851 759 1056 191 216 335 356 540 528 51 43 123 103 160 134 247 207 292 266 253 333 -52 88 -361 149 -638 127z" fill="#2DD4BF"/></g></g></g></svg>
EOF
# round icon
cat > "$TMP/round.svg" <<'EOF'
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><circle cx="32" cy="32" r="32" fill="#0B1F3A"/><g transform="translate(9.6 9.6) scale(0.7)"><g transform="translate(-51.3 6.1) scale(0.03556)"><g transform="translate(0 1232) scale(0.25 -0.25)"><path d="M10626 3768 c-578 -31 -1016 -329 -1468 -1002 -31 -46 -104 -154 -162 -240 -58 -86 -141 -210 -184 -276 -490 -751 -888 -1177 -1438 -1537 -181 -118 -223 -161 -224 -225 -1 -164 405 -257 846 -196 419 59 786 307 1166 788 143 182 215 284 425 602 523 793 783 1108 1211 1469 31 26 95 79 142 119 142 119 242 208 264 235 106 127 26 207 -249 249 -103 16 -209 20 -329 14z M7574 3758 c-312 -32 -451 -85 -451 -171 0 -44 19 -62 237 -229 425 -324 766 -669 1090 -1103 107 -144 111 -144 229 40 34 55 91 142 125 194 34 52 83 127 108 166 25 39 74 110 108 157 127 177 131 156 -78 384 -394 431 -844 616 -1368 562z M9990 2003 c-25 -11 -83 -93 -295 -413 -58 -88 -144 -214 -192 -280 -124 -174 -124 -178 -58 -260 309 -381 542 -575 825 -687 426 -168 1095 -128 1304 79 86 85 61 136 -106 220 -108 54 -259 143 -337 199 -230 164 -369 285 -548 477 -173 185 -256 286 -455 549 -86 115 -105 131 -138 116z" fill="#fff"/><path d="M10601 3768 c-578 -48 -998 -340 -1443 -1002 -31 -46 -109 -162 -173 -257 -64 -95 -146 -218 -182 -274 -36 -55 -85 -129 -109 -163 -24 -34 -67 -97 -96 -139 -360 -521 -741 -899 -1244 -1233 -166 -110 -204 -150 -204 -212 1 -152 368 -249 772 -205 456 50 842 292 1205 753 28 36 73 93 98 125 70 88 226 311 302 429 282 440 577 851 759 1056 191 216 335 356 540 528 51 43 123 103 160 134 247 207 292 266 253 333 -52 88 -361 149 -638 127z" fill="#2DD4BF"/></g></g></g></svg>
EOF
# adaptive foreground (108dp canvas, glyph inside the 66dp safe zone)
cat > "$TMP/fg.svg" <<'EOF'
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 108 108"><g transform="translate(54 54) scale(1.05) translate(-32 -32)"><g transform="translate(-51.3 6.1) scale(0.03556)"><g transform="translate(0 1232) scale(0.25 -0.25)"><path d="M10626 3768 c-578 -31 -1016 -329 -1468 -1002 -31 -46 -104 -154 -162 -240 -58 -86 -141 -210 -184 -276 -490 -751 -888 -1177 -1438 -1537 -181 -118 -223 -161 -224 -225 -1 -164 405 -257 846 -196 419 59 786 307 1166 788 143 182 215 284 425 602 523 793 783 1108 1211 1469 31 26 95 79 142 119 142 119 242 208 264 235 106 127 26 207 -249 249 -103 16 -209 20 -329 14z M7574 3758 c-312 -32 -451 -85 -451 -171 0 -44 19 -62 237 -229 425 -324 766 -669 1090 -1103 107 -144 111 -144 229 40 34 55 91 142 125 194 34 52 83 127 108 166 25 39 74 110 108 157 127 177 131 156 -78 384 -394 431 -844 616 -1368 562z M9990 2003 c-25 -11 -83 -93 -295 -413 -58 -88 -144 -214 -192 -280 -124 -174 -124 -178 -58 -260 309 -381 542 -575 825 -687 426 -168 1095 -128 1304 79 86 85 61 136 -106 220 -108 54 -259 143 -337 199 -230 164 -369 285 -548 477 -173 185 -256 286 -455 549 -86 115 -105 131 -138 116z" fill="#fff"/><path d="M10601 3768 c-578 -48 -998 -340 -1443 -1002 -31 -46 -109 -162 -173 -257 -64 -95 -146 -218 -182 -274 -36 -55 -85 -129 -109 -163 -24 -34 -67 -97 -96 -139 -360 -521 -741 -899 -1244 -1233 -166 -110 -204 -150 -204 -212 1 -152 368 -249 772 -205 456 50 842 292 1205 753 28 36 73 93 98 125 70 88 226 311 302 429 282 440 577 851 759 1056 191 216 335 356 540 528 51 43 123 103 160 134 247 207 292 266 253 333 -52 88 -361 149 -638 127z" fill="#2DD4BF"/></g></g></g></svg>
EOF

for d in mdpi:48:108 hdpi:72:162 xhdpi:96:216 xxhdpi:144:324 xxxhdpi:192:432; do
  IFS=: read -r name size fg <<<"$d"
  dir="$RES/mipmap-$name"
  mkdir -p "$dir"
  rsvg-convert -w "$size" -h "$size" "$TMP/icon.svg" -o "$dir/ic_launcher.png"
  rsvg-convert -w "$size" -h "$size" "$TMP/round.svg" -o "$dir/ic_launcher_round.png"
  rsvg-convert -w "$fg" -h "$fg" "$TMP/fg.svg" -o "$dir/ic_launcher_foreground.png"
done

# launch screen (Android 7–11; Android 12+ uses the system splash with the icon + brand colour, see styles.xml)
splash() { # w h
  cat <<EOF
<svg xmlns="http://www.w3.org/2000/svg" width="$1" height="$2" viewBox="0 0 $1 $2"><rect width="$1" height="$2" fill="#0B1F3A"/><g transform="translate($(( $1 / 2 )) $(( $2 / 2 ))) scale(4) translate(-32 -32)"><g transform="translate(-51.3 6.1) scale(0.03556)"><g transform="translate(0 1232) scale(0.25 -0.25)"><path d="M10626 3768 c-578 -31 -1016 -329 -1468 -1002 -31 -46 -104 -154 -162 -240 -58 -86 -141 -210 -184 -276 -490 -751 -888 -1177 -1438 -1537 -181 -118 -223 -161 -224 -225 -1 -164 405 -257 846 -196 419 59 786 307 1166 788 143 182 215 284 425 602 523 793 783 1108 1211 1469 31 26 95 79 142 119 142 119 242 208 264 235 106 127 26 207 -249 249 -103 16 -209 20 -329 14z M7574 3758 c-312 -32 -451 -85 -451 -171 0 -44 19 -62 237 -229 425 -324 766 -669 1090 -1103 107 -144 111 -144 229 40 34 55 91 142 125 194 34 52 83 127 108 166 25 39 74 110 108 157 127 177 131 156 -78 384 -394 431 -844 616 -1368 562z M9990 2003 c-25 -11 -83 -93 -295 -413 -58 -88 -144 -214 -192 -280 -124 -174 -124 -178 -58 -260 309 -381 542 -575 825 -687 426 -168 1095 -128 1304 79 86 85 61 136 -106 220 -108 54 -259 143 -337 199 -230 164 -369 285 -548 477 -173 185 -256 286 -455 549 -86 115 -105 131 -138 116z" fill="#fff"/><path d="M10601 3768 c-578 -48 -998 -340 -1443 -1002 -31 -46 -109 -162 -173 -257 -64 -95 -146 -218 -182 -274 -36 -55 -85 -129 -109 -163 -24 -34 -67 -97 -96 -139 -360 -521 -741 -899 -1244 -1233 -166 -110 -204 -150 -204 -212 1 -152 368 -249 772 -205 456 50 842 292 1205 753 28 36 73 93 98 125 70 88 226 311 302 429 282 440 577 851 759 1056 191 216 335 356 540 528 51 43 123 103 160 134 247 207 292 266 253 333 -52 88 -361 149 -638 127z" fill="#2DD4BF"/></g></g></g></svg>
EOF
}
splash 720 1280 > "$TMP/port.svg"
splash 1280 720 > "$TMP/land.svg"
rsvg-convert "$TMP/port.svg" -o "$RES/drawable/splash.png"
for d in "$RES"/drawable-port-*; do rsvg-convert "$TMP/port.svg" -o "$d/splash.png"; done
for d in "$RES"/drawable-land-*; do rsvg-convert "$TMP/land.svg" -o "$d/splash.png"; done

mkdir -p "$RES/values"
cat > "$RES/values/ic_launcher_background.xml" <<'EOF'
<?xml version="1.0" encoding="utf-8"?>
<resources>
    <color name="ic_launcher_background">#0B1F3A</color>
</resources>
EOF
rm -rf "$TMP"
echo "icons generated"
